-- ═══ 2. Order number sequence ═══════════════════════════════════════════════
-- SP-YYMM-NNNNNN: the counter never resets, so numbers stay unique across
-- months; gaps are allowed (a failed placement uses a number).
CREATE SEQUENCE "order_number_seq" AS INTEGER MINVALUE 1 MAXVALUE 999999 NO CYCLE;

-- ═══ 3. CHECK constraints ════════════════════════════════════════════════════
ALTER TABLE "order" ADD CONSTRAINT "order_number_check"
  CHECK ("order_number" ~ '^SP-[0-9]{4}-[0-9]{6}$');
ALTER TABLE "order" ADD CONSTRAINT "order_amounts_check"
  CHECK ("subtotal_paise" > 0 AND "discount_paise" >= 0 AND "discount_paise" <= "subtotal_paise"
     AND "shipping_paise" >= 0 AND "cod_fee_paise" >= 0 AND "tax_paise" >= 0);
ALTER TABLE "order" ADD CONSTRAINT "order_total_check"
  CHECK ("total_paise" = "subtotal_paise" - "discount_paise" + "shipping_paise" + "cod_fee_paise"
     AND "tax_paise" <= "total_paise");
ALTER TABLE "order" ADD CONSTRAINT "order_currency_check"
  CHECK ("currency" = 'INR');
ALTER TABLE "order" ADD CONSTRAINT "order_phone_check"
  CHECK ("phone" ~ '^\+91[6-9][0-9]{9}$');
ALTER TABLE "order" ADD CONSTRAINT "order_cod_fee_check"
  CHECK ("payment_method" = 'COD' OR "cod_fee_paise" = 0);
ALTER TABLE "order" ADD CONSTRAINT "order_access_token_hash_check"
  CHECK (octet_length("access_token_hash") = 32);
ALTER TABLE "order" ADD CONSTRAINT "order_attention_check"
  CHECK ("needs_attention" OR "attention_reason" IS NULL);
ALTER TABLE "order_item" ADD CONSTRAINT "order_item_quantity_check"
  CHECK ("quantity" BETWEEN 1 AND 10);
ALTER TABLE "order_item" ADD CONSTRAINT "order_item_amounts_check"
  CHECK ("unit_price_paise" > 0 AND "line_total_paise" = "unit_price_paise" * "quantity");
ALTER TABLE "order_item" ADD CONSTRAINT "order_item_gst_rate_check"
  CHECK ("gst_rate_bps" IS NULL OR "gst_rate_bps" BETWEEN 0 AND 10000);
ALTER TABLE "payment" ADD CONSTRAINT "payment_amount_check"
  CHECK ("amount_paise" > 0);
ALTER TABLE "payment" ADD CONSTRAINT "payment_method_status_check"
  CHECK (("method" = 'PREPAID' AND "status" IN ('CREATED', 'AUTHORISED', 'CAPTURED', 'FAILED', 'EXPIRED', 'REFUND_PENDING', 'REFUNDED', 'REFUND_FAILED'))
      OR ("method" = 'COD' AND "status" IN ('PENDING', 'COLLECTED', 'NOT_COLLECTED', 'REFUND_PENDING', 'REFUNDED', 'REFUND_FAILED')));
ALTER TABLE "refund" ADD CONSTRAINT "refund_amount_check"
  CHECK ("amount_paise" > 0);
ALTER TABLE "refund" ADD CONSTRAINT "refund_reason_check"
  CHECK (char_length("reason") BETWEEN 1 AND 500);
ALTER TABLE "shipment" ADD CONSTRAINT "shipment_text_check"
  CHECK (char_length("courier_name") BETWEEN 1 AND 100 AND char_length("tracking_number") BETWEEN 1 AND 100);
ALTER TABLE "gst_rule" ADD CONSTRAINT "gst_rule_rates_check"
  CHECK ("rate_bps_at_or_below" BETWEEN 0 AND 10000
     AND ("rate_bps_above" IS NULL OR "rate_bps_above" BETWEEN 0 AND 10000)
     AND (("threshold_paise" IS NULL) = ("rate_bps_above" IS NULL))
     AND ("threshold_paise" IS NULL OR "threshold_paise" > 0));
ALTER TABLE "gst_rule" ADD CONSTRAINT "gst_rule_effective_check"
  CHECK ("effective_to" IS NULL OR "effective_to" > "effective_from");
ALTER TABLE "gst_rule" ADD CONSTRAINT "gst_rule_hsn_prefix_check"
  CHECK ("hsn_prefix" ~ '^[0-9]{0,8}$');

-- ═══ 4. Append-only order history (D-057) ═══════════════════════════════════
CREATE TRIGGER "order_status_event_append_only"
  BEFORE UPDATE OR DELETE ON "order_status_event"
  FOR EACH ROW EXECUTE FUNCTION "reject_append_only_change"();
CREATE TRIGGER "order_status_event_no_truncate"
  BEFORE TRUNCATE ON "order_status_event"
  FOR EACH STATEMENT EXECUTE FUNCTION "reject_append_only_change"();
